DROP TABLE IF EXISTS users;

DROP TABLE IF EXISTS tracks;

DROP TABLE IF EXISTS metadata;

DROP TABLE IF EXISTS track_authors;

DROP TABLE IF EXISTS track_links;

DROP TABLE IF EXISTS gpx_files;

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";


CREATE TABLE IF NOT EXISTS "tracks" (
  "id" UUID PRIMARY KEY,
  "name" varchar(120),
  "description" varchar (255),
  "type" varchar (120),
  "duration" time,
  "complexity" varchar(120),
  "points" geometry(LineStringZ, 4326) NOT NULL
);

CREATE TABLE IF NOT EXISTS "metadata" (
  "metadata_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "metadata_name" varchar(120),
  "author_id" bigint,
  "link_id" bigint
);

CREATE TABLE IF NOT EXISTS "track_authors" (
  "author_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "author_name" varchar(120)
);

CREATE TABLE IF NOT EXISTS "track_links" (
  "link_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "url" varchar(120)
);

CREATE TABLE IF NOT EXISTS "gpx_files" (
  "track_id" UUID PRIMARY KEY,
  "version" varchar(120),
  "creator" varchar(120),
  "schema_location" varchar(120),
  "metadata_id" bigint,

);

CREATE TABLE IF NOT EXISTS "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120)
);

ALTER TABLE "metadata" ADD FOREIGN KEY ("author_id") REFERENCES "track_authors" ("author_id");
ALTER TABLE "metadata" ADD FOREIGN KEY ("link_id") REFERENCES "track_links" ("link_id");
ALTER TABLE "gpx_files" ADD FOREIGN KEY ("metadata_id") REFERENCES "metadata" ("metadata_id");
ALTER TABLE "gpx_files" ADD FOREIGN KEY ("track_id") REFERENCES "tracks" ("id");